-- 大众日常常用药品知识补录（感冒类 / 消化类 / 复方降压 / 常用中成药）
-- 数据结构参照人卫用药助手药品说明书栏目：成分/性状/规格/适应症/用法用量/不良反应/禁忌/注意事项/特殊人群/药理/相互作用
-- 内容依据各药品国家药监局批准说明书编写；复方药成分书写沿用库内既有惯例（含每片/每袋含量，便于比对成分）
USE medication_radar;

START TRANSACTION;

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('感冒灵颗粒', '["感冒灵", "999感冒灵"]', '感冒用药', '每袋含对乙酰氨基酚200mg、马来酸氯苯那敏3mg、咖啡因20mg，及三叉苦、金盏银盘、野菊花、岗梅、薄荷油等中药成份', '浅棕色至深棕色的颗粒；气香，味甜、微苦', '每袋装10克（含对乙酰氨基酚0.2克）', '颗粒剂', '解热镇痛。用于感冒引起的头痛、发热、鼻塞、流涕、咽痛', '开水冲服。一次10克（1袋），一日3次', '偶见皮疹、荨麻疹、药热及粒细胞减少；可见困倦、嗜睡、口渴、虚弱感；长期大量用药会导致肝肾功能异常', '严重肝肾功能不全者禁用', '忌烟、酒及辛辣、生冷、油腻食物；不宜在服药期间同时服用滋补性中药；不能同时服用与本品成份相似的其他抗感冒药；脾胃虚寒（怕冷、大便稀）者慎用；服药期间不得驾驶车辆、高空作业', '孕妇及哺乳期妇女慎用；儿童、年老体弱者应在医师指导下服用；肝肾功能不全者慎用', '对乙酰氨基酚解热镇痛；马来酸氯苯那敏减轻流涕、打喷嚏；咖啡因缓解头痛乏力；中药成份辛凉解表、清热解毒', '与其他含对乙酰氨基酚的感冒药或退烧药（如氨咖黄敏、维C银翘片、对乙酰氨基酚片）同服，可致对乙酰氨基酚超量，肝损伤风险明显升高', '退热用药不超过3天，镇痛不超过5天；注意有无皮疹、嗜睡加重、尿黄乏力等肝损表现', '服药期间禁止饮酒或饮用含酒精的饮料')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('复方氨酚烷胺片', '["复方氨酚烷胺", "感康", "快克"]', '感冒用药', '每片含对乙酰氨基酚250mg、盐酸金刚烷胺100mg、人工牛黄10mg、咖啡因15mg、马来酸氯苯那敏2mg', '淡黄色片', '每片含对乙酰氨基酚0.25克', '片剂', '适用于缓解普通感冒及流行性感冒引起的发热、头痛、四肢酸痛、打喷嚏、流鼻涕、鼻塞、咽痛等症状', '口服。成人一次1片，一日2次', '有时有轻度头晕、乏力、恶心、上腹不适、口干、食欲缺乏和皮疹等，可自行恢复', '严重肝肾功能不全者禁用', '服药后不得驾驶机车船、从事高空作业、机械作业及操作精密仪器；服用期间不得饮酒或饮用含酒精的饮料；不能同时服用与本品成份相似的其他抗感冒药；前列腺肥大、青光眼患者及老年人应在医师指导下使用', '孕妇及哺乳期妇女慎用；1岁以下儿童应在医师指导下使用；肝肾功能不全者慎用', '对乙酰氨基酚解热镇痛；盐酸金刚烷胺抗甲型流感病毒；马来酸氯苯那敏减轻流涕打喷嚏；咖啡因增强解热镇痛效果并缓解乏力；人工牛黄清热', '与其他感冒药（感冒灵、氨咖黄敏、维C银翘片等）叠加，对乙酰氨基酚与氯苯那敏易超量；金刚烷胺与中枢镇静药叠加加重嗜睡', '连续用药不超过7天；发热或疼痛不缓解应就医；注意头晕、嗜睡程度', '服药期间禁止饮酒；老年人注意排尿困难与意识混浊等不良反应')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('维C银翘片', '["维C银翘", "维生素C银翘片"]', '感冒用药', '每片含对乙酰氨基酚105mg、马来酸氯苯那敏1.05mg、维生素C 49.5mg，及山银花、连翘、荆芥、淡豆豉、淡竹叶、牛蒡子、芦根、桔梗、甘草等中药成份', '薄膜衣片，除去包衣后显灰褐色至褐绿色；气香，味微苦', '每片含对乙酰氨基酚105毫克', '片剂', '辛凉解表，清热解毒。用于流行性感冒引起的发热头痛、咳嗽、口干、咽喉疼痛', '口服。一次2片，一日3次', '可见困倦、嗜睡、口渴、虚弱感；偶见皮疹、荨麻疹、药热及粒细胞减少；长期大量用药会导致肝肾功能异常', '严重肝肾功能不全者禁用', '忌烟、酒及辛辣、生冷、油腻食物；不宜在服药期间同时服用滋补性中药；不适用于风寒感冒（怕冷明显、无汗、流清涕）；不能同时服用与本品成份相似的其他抗感冒药；服药期间不得驾驶车辆及高空作业', '孕妇及哺乳期妇女慎用；膀胱颈梗阻、甲状腺功能亢进、青光眼、高血压和前列腺肥大者慎用；儿童、年老体弱者应在医师指导下服用', '银花、连翘辛凉解表、清热解毒；对乙酰氨基酚解热镇痛；马来酸氯苯那敏抗过敏；维生素C增强抵抗力', '与其他含对乙酰氨基酚的感冒药或退烧药同服可致对乙酰氨基酚超量，肝损伤风险升高', '用药3-7天症状未缓解应就医；注意嗜睡与皮疹', '服药期间禁止饮酒或饮用含酒精的饮料')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('氨咖黄敏胶囊', '["氨咖黄敏", "速效伤风胶囊"]', '感冒用药', '每粒含对乙酰氨基酚250mg、咖啡因15mg、马来酸氯苯那敏1mg、人工牛黄10mg', '硬胶囊剂，内容物为着色混合颗粒', '复方制剂，每粒含对乙酰氨基酚250毫克', '硬胶囊剂', '适用于缓解普通感冒及流行性感冒引起的发热、头痛、四肢酸痛、打喷嚏、流鼻涕、鼻塞、咽痛等症状', '口服。成人一次1-2粒，一日3次', '有时有轻度头晕、乏力、恶心、上腹不适、口干、食欲缺乏和皮疹等，可自行恢复', '严重肝肾功能不全者禁用', '服药后不得驾驶车辆及高空作业；服用期间不得饮酒或饮用含酒精的饮料；不能同时服用与本品成份相似的其他抗感冒药', '孕妇及哺乳期妇女慎用；肝肾功能不全者慎用；老年人应在医师指导下使用', '对乙酰氨基酚解热镇痛；咖啡因协同镇痛、缓解乏力；马来酸氯苯那敏抗过敏；人工牛黄清热', '与其他含对乙酰氨基酚的感冒药叠加易致超量；含氯苯那敏与镇静药叠加加重嗜睡', '连续用药不超过7天；症状不缓解应就医', '服药期间禁止饮酒')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('板蓝根颗粒', '["板蓝根"]', '感冒用药', '板蓝根；辅料为蔗糖、糊精', '浅棕黄色至棕褐色的颗粒；味甜、微苦', '每袋装10克（另有每袋5克规格）', '颗粒剂', '清热解毒，凉血利咽。用于肺胃热盛所致的咽喉肿痛、口咽干燥；急性扁桃体炎见上述证候者', '开水冲服。一次5-10克，一日3-4次', '个别患者服药后出现恶心、腹泻等消化道不适；偶见皮疹', '对本品及成份过敏者禁用；风寒感冒者不适用', '忌烟、酒及辛辣、生冷、油腻食物；不宜在服药期间同时服用滋补性中药；脾胃虚寒者（怕冷、大便稀、腹部凉）慎用', '糖尿病患者应选用无糖型并在医师指导下服用；儿童、孕妇、哺乳期妇女、年老体弱及高血压、心脏病、肝病、肾病等慢性病严重者应在医师指导下服用', '板蓝根清热解毒、凉血利咽，具有抗病毒、抗菌、抗炎与解热作用', '与双黄连、连花清瘟等其他清热解毒类中成药自行叠加，易致脾胃受凉、腹泻，不建议同时服用多种同类', '服药3天症状无缓解应就医', '风寒感冒（怕冷、无汗、流清涕）者不适用；含蔗糖，糖尿病者选无糖型')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('双黄连口服液', '["双黄连"]', '感冒用药', '金银花、黄芩、连翘；辅料为蔗糖', '棕红色的澄清液体；味甜、微苦', '每支装10毫升', '口服液', '疏风解表，清热解毒。用于外感风热所致的感冒，症见发热、咳嗽、咽痛', '口服。一次20毫升（2支），一日3次；小儿酌减或遵医嘱', '偶见皮疹、瘙痒等过敏反应；个别出现恶心、呕吐、腹泻', '风寒感冒者禁用（怕冷、无汗、流清涕）', '忌烟、酒及辛辣、生冷、油腻食物；不宜在服药期间同时服用滋补性中药；脾胃虚寒者慎用', '糖尿病患者慎用（含蔗糖）；儿童、孕妇、哺乳期妇女、年老体弱者应在医师指导下服用；高血压、心脏病、肝病、肾病等慢性病严重者应遵医嘱', '金银花、连翘清热解毒透表，黄芩清肺火，具有解热、抗炎、抗菌抗病毒作用', '与板蓝根、连花清瘟等其他清热解毒类中成药自行叠加，易伤脾胃引起腹泻', '服药3天症状无缓解应就医', '风寒感冒不适用；含蔗糖，糖尿病者慎用')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('连花清瘟胶囊', '["连花清瘟"]', '感冒用药', '连翘、金银花、炙麻黄、炒苦杏仁、石膏、板蓝根、绵马贯众、鱼腥草、广藿香、大黄、红景天、薄荷脑、甘草', '硬胶囊，内容物为棕黄色至黄褐色的颗粒和粉末；气微香，味微苦', '每粒装0.35克', '硬胶囊剂', '清瘟解毒，宣肺泄热。用于治疗流行性感冒属热毒袭肺证，症见发热、恶寒、肌肉酸痛、鼻塞流涕、咳嗽、头痛、咽干咽痛、舌偏红、苔黄或黄腻', '口服。一次4粒，一日3次', '服药期间可见恶心、呕吐、腹泻、腹部不适；偶见皮疹、瘙痒', '对本品成份过敏者禁用；风寒感冒者不适用', '忌烟、酒及辛辣、生冷、油腻食物；不宜在服药期间同时服用滋补性中药；高血压、心脏病患者慎用（含麻黄）；不能同时服用与本品成份相似的其他抗感冒药', '运动员慎用；儿童、孕妇、哺乳期妇女、年老体弱及脾虚便溏者应在医师指导下服用；高血压、心脏病、肝病、糖尿病、肾病等慢性病严重者应遵医嘱', '麻杏石甘汤与银翘散化裁，宣肺泄热、清瘟解毒，具有解热、抗炎、抗流感病毒、止咳化痰作用', '与其他含麻黄碱类感冒药叠加，心悸、血压升高风险；与其他清热解毒中成药叠加伤脾胃', '高血压患者服药期间注意血压波动与心悸；用药3天症状无缓解应就医', '含麻黄，高血压、冠心病、心律失常者慎用；与降压药同用可能减弱降压效果，需监测血压')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('小柴胡颗粒', '["小柴胡"]', '感冒用药', '柴胡、黄芩、姜半夏、党参、生姜、甘草、大枣；辅料为蔗糖', '黄色至棕褐色的颗粒；味甜', '每袋装10克', '颗粒剂', '解表散热，疏肝和胃。用于外感病邪犯少阳证，症见寒热往来、胸胁苦满、食欲不振、心烦喜呕、口苦咽干', '开水冲服。一次1袋（10克），一日3次', '个别患者出现食欲下降、腹胀；尚不明确', '对本品成份过敏者禁用；风寒感冒者不适用', '忌烟、酒及辛辣、生冷、油腻食物；不宜在服药期间同时服用滋补性中药', '高血压、心脏病、肝病、糖尿病、肾病等慢性病患者应在医师指导下服用；儿童、孕妇、年老体弱者应在医师指导下服用；糖尿病者注意含糖', '和解少阳：柴胡、黄芩疏解退热，姜半夏、生姜和胃止呕，党参、大枣扶正，甘草调和', '与退烧药（对乙酰氨基酚等）叠加注意汗多体虚；与其他感冒药叠加注意成分重复', '寒热不退超过3天应就医', '感冒迁延数日、食欲差、口苦者适用')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('藿香正气水', '["藿香正气"]', '感冒用药', '苍术、陈皮、姜厚朴、白芷、茯苓、大腹皮、生半夏、甘草浸膏、广藿香油、紫苏叶油；辅料为乙醇（含酒精量40%-50%）', '深棕色的澄清液体（久贮略有浑浊）；味辛、苦', '每支装10毫升', '酊剂', '解表化湿，理气和中。用于外感风寒、内伤湿滞或夏伤暑湿所致的感冒，症见头痛昏重、脘腹胀痛、呕吐泄泻；胃肠型感冒见上述证候者', '口服。一次5-10毫升，一日2次，用时摇匀', '本品含乙醇（酒精），服后可出现面部潮红、心跳加快；偶见皮疹、恶心、呕吐', '对本品及酒精过敏者禁用；服药期间及停药后数日内不得使用头孢菌素类、硝基咪唑类（甲硝唑、替硝唑、奥硝唑等）药物', '忌烟、酒及辛辣、生冷、油腻食物；服药后不得驾驶车辆及高空作业（含酒精）；不宜在服药期间同时服用滋补性中药；吐泻严重者应及时就医；肝病者慎用', '孕妇慎用；儿童、年老体弱者应在医师指导下服用；酒精过敏者禁用；肝病患者慎用', '广藿香油化湿醒脾，紫苏叶油散寒解表，苍术、厚朴燥湿行气，具有调节胃肠功能、止吐止泻作用', '与其他含醇制剂叠加增加酒精摄入；与镇静催眠药叠加加重中枢抑制', '注意酒精相关反应（面红、心悸、嗜睡）及与抗菌药物的间隔', '服用本品期间及停药后数日内严禁使用头孢类、甲硝唑等药物：可致双硫仑样反应（面部潮红、头痛、心悸、呼吸困难，严重可危及生命）')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('牛黄解毒片', '["牛黄解毒"]', '感冒用药', '人工牛黄、雄黄、石膏、大黄、黄芩、桔梗、冰片、甘草', '素片或包衣片，除去包衣后显棕黄色；有冰片香气，味微苦、辛', '每片重0.27克（素片）', '片剂', '清热解毒。用于火热内盛所致的咽喉肿痛、牙龈肿痛、口舌生疮、目赤肿痛', '口服。一次2-3片，一日2-3次', '偶见腹泻、腹部不适；长期使用可致依赖性便秘', '孕妇禁用；对本品成份过敏者禁用', '忌烟、酒及辛辣、油腻食物；本品不宜长期、大量服用（含雄黄）；脾胃虚寒者慎用；不宜与滋补性中药同服', '孕妇禁用；儿童、年老体弱者及哺乳期妇女应在医师指导下服用；肝肾功能不全者慎用', '牛黄、大黄清热泻火，石膏、黄芩清热，冰片消肿止痛；具有抗炎、泻下作用', '与其他清热泻火类中成药叠加易致腹泻、伤脾胃', '连续用药不超过3天；注意大便次数与腹痛', '含雄黄，不可超量、长期服用；与含雄黄的其他中成药（如安宫牛黄丸）同服警惕砷蓄积')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('健胃消食片', '["健胃消食"]', '消化', '太子参、陈皮、山药、炒麦芽、炒山楂；辅料为蔗糖、糊精', '淡棕黄色的片；气略香，味微甜、酸', '每片重0.5克', '片剂', '健胃消食。用于脾胃虚弱所致的食积，症见不思饮食、嗳腐酸臭、脘腹胀满；消化不良见上述证候者', '口服，可以咀嚼。成人一次4-6片，一日3次；小儿二岁至四岁一次2片，五岁至八岁一次3片，九岁至十四岁一次4片，一日3次', '个别患者出现口干、便溏；尚不明确', '对本品成份过敏者禁用', '忌辛辣、生冷、油腻食物；服药一周症状无缓解应就医；按用法用量服用，小儿应在医师指导下服用', '儿童、孕妇、哺乳期妇女应在医师指导下服用；糖尿病者慎用（含蔗糖）；高血压、心脏病、肝病、肾病等慢性病严重者应遵医嘱', '山楂、麦芽消食化积，太子参、山药健脾益气，陈皮理气和胃', '与多潘立酮等促胃动力药叠加属重复用药，无需同时服用', '腹胀持续不缓解需排查器质性疾病', '含蔗糖，糖尿病者慎用')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('口服补液盐散', '["口服补液盐", "ORS"]', '消化', '每袋含氯化钠2.6克、枸橼酸钠2.9克、氯化钾1.5克、无水葡萄糖13.5克', '白色结晶性粉末', '每袋14.75克（口服补液盐散Ⅲ）', '散剂', '治疗和预防急、慢性腹泻造成的轻度脱水与电解质紊乱', '临用时将一袋（14.75克）溶于250毫升温开水中，随时口服。成人轻度脱水一日补充2-3升，分次饮用；儿童按脱水程度与体重遵医嘱', '偶见恶心、呕吐（多为饮用过快），减慢饮用速度可缓解', '无尿或严重脱水者禁用（应静脉补液）；肠梗阻、肠麻痹、肠穿孔者禁用；葡萄糖吸收障碍者禁用', '必须按说明书浓度配制，不得随意加糖、加盐或稀释；腹泻超过2天或出现高热、血便、持续呕吐应立即就医；肾功能不全者慎用', '孕妇及哺乳期妇女可按需使用；婴幼儿使用口服补液盐Ⅲ应遵医嘱', '按世界卫生组织推荐的低渗配方，钠与葡萄糖协同转运促进肠道对水和电解质的吸收，有效纠正轻中度脱水', '与含钾制剂、保钾利尿剂同用时注意血钾升高风险', '观察尿量、口渴程度与精神状态；老年人注意监测血钠血钾', '心功能不全、肾功能不全的老年人大量饮用前应咨询医生（钠钾负荷）')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('缬沙坦氨氯地平片', '["缬沙坦氨氯地平", "倍博特"]', '心血管', '每片含缬沙坦80毫克、苯磺酸氨氯地平5毫克（以氨氯地平计）', '薄膜衣片，除去包衣后显白色或类白色', '每片含缬沙坦80mg/氨氯地平5mg', '片剂', '治疗原发性高血压。用于单药治疗不能充分控制血压的患者', '口服。一次1片，一日1次，餐前餐后均可；血压控制不满意时遵医嘱调整剂量', '常见外周水肿、头晕、头痛、疲乏、恶心；偶见体位性低血压、咳嗽', '对本品任何成份或二氢吡啶类钙拮抗剂过敏者禁用；妊娠妇女禁用；重度肝功能不全、胆汁淤积患者禁用', '开始治疗及调整剂量时注意体位性低血压（老年人尤甚）；定期监测血压、血钾、肾功能；血容量不足者首剂减量', '孕妇禁用（可致胎儿损害）；哺乳期不推荐；65岁以上老年人宜低剂量起始；儿童不推荐', '缬沙坦阻断血管紧张素Ⅱ受体（ARB），氨氯地平扩张外周动脉（二氢吡啶类CCB），双机制协同降压；复方较单药加量水肿发生率更低', '与单方缬沙坦、氨氯地平或其他ARB、地平类、含此类成分的复方降压药叠加，可致血压过度下降、低血压', '血压（尤其立位血压）、血钾、血肌酐；调整期每周监测', '与补钾剂、螺内酯等保钾药物合用警惕高钾血症；与地高辛合用需监测地高辛浓度')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('氯沙坦钾氢氯噻嗪片', '["氯沙坦钾氢氯噻嗪", "海捷亚"]', '心血管', '每片含氯沙坦钾50毫克、氢氯噻嗪12.5毫克', '黄色椭圆形薄膜衣片，除去包衣后显白色', '每片含氯沙坦钾50mg/氢氯噻嗪12.5mg', '片剂', '用于治疗高血压，适用于需要联合用药的患者', '口服。一次1片，一日1次；根据血压反应在医师指导下调整剂量', '常见头晕、疲乏；氢氯噻嗪可致低钾血症、低钠血症、血尿酸升高、血糖升高；偶见体位性低血压', '妊娠妇女禁用；无尿患者禁用；对本品或磺胺类药物过敏者禁用', '定期监测电解质（血钾、血钠）、血糖、血尿酸；痛风患者慎用；糖尿病患者慎用噻嗪类利尿剂；血容量不足者首剂低血压风险', '孕妇禁用；哺乳期不推荐；老年人与肾功能不全者慎用，宜低剂量起始', '氯沙坦阻断血管紧张素Ⅱ受体，氢氯噻嗪利尿减少血容量；协同降压，且氯沙坦可减轻噻嗪类所致低钾与高尿酸', '与单方氯沙坦、氢氯噻嗪或其他ARB、利尿剂、含此类成分的复方降压药叠加，可致低血压与电解质紊乱', '血钾（起始及剂量调整时）、血尿酸、血糖、血压', '痛风患者慎用；与地高辛合用注意低钾诱发心律失常')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('厄贝沙坦氢氯噻嗪片', '["厄贝沙坦氢氯噻嗪", "安博诺"]', '心血管', '每片含厄贝沙坦150毫克、氢氯噻嗪12.5毫克', '薄膜衣片，除去包衣后显类白色或淡粉色', '每片含厄贝沙坦150mg/氢氯噻嗪12.5mg', '片剂', '用于治疗原发性高血压。该固定剂量复方用于单药不能充分控制血压的患者', '口服。一次1片，一日1次，空腹或餐后服用；根据血压反应调整', '常见头晕、恶心、疲乏；偶见体位性低血压、肌痛、血钾异常（低钾为主）', '妊娠妇女禁用；无尿患者禁用；对磺胺衍生物过敏者禁用', '监测电解质与肾功能；血容量不足者首剂低血压风险；痛风患者慎用；避免与其他升钾或降钾因素叠加', '孕妇禁用；哺乳期不推荐；老年人无需特殊起始调整，但降压宜平缓', '厄贝沙坦阻断血管紧张素Ⅱ受体，氢氯噻嗪利尿降压；协同起效并减轻噻嗪类低钾、高尿酸副作用', '与单方厄贝沙坦、氢氯噻嗪或其他ARB、利尿剂及含此类成分复方降压药叠加，可致低血压、电解质紊乱', '血压、血钾、血肌酐、血尿酸', '择期手术前应告知麻醉医师正在服用本品')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('复方利血平氨苯蝶啶片', '["北京降压0号", "降压0号"]', '心血管', '每片含利血平0.1毫克、氨苯蝶啶12.5毫克、氢氯噻嗪12.5毫克、硫酸双肼屈嗪12.5毫克', '薄膜衣片，除去包衣后显淡黄色', '复方制剂（每片含利血平0.1mg等四种成份）', '片剂', '用于治疗轻、中度高血压', '口服。一次1片，一日1次；血压稳定后可遵医嘱改为隔日1片维持', '偶见恶心、头胀、乏力、鼻塞、嗜睡；长期服用利血平可致抑郁；利尿成分可致电解质紊乱', '胃及十二指肠溃疡患者禁用；抑郁症患者禁用；对本品任何成份过敏者禁用', '老年患者慎用；长期服药注意情绪与睡眠变化；痛风、糖尿病、肾结石患者慎用（噻嗪类影响尿酸与血糖）；不能与单胺氧化酶抑制剂合用', '孕妇及哺乳期妇女慎用；儿童不推荐；老年人宜低剂量起始并注意体位性低血压', '利血平耗竭交感神经递质降压，双肼屈嗪直接扩张血管，氢氯噻嗪利钠利尿，氨苯蝶啶保钾以对抗低钾', '与单方利血平、噻嗪类利尿剂或其他降压药叠加，可致血压过低与电解质紊乱', '血压、血钾、情绪与睡眠、长期服药者注意胃部症状', '消化性溃疡、精神抑郁者不宜使用；手术前应告知医生用药史（利血平影响麻醉管理）')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('速效救心丸', '[]', '心血管', '川芎、冰片', '棕黄色的滴丸；气凉，味微苦', '每丸重40毫克', '滴丸剂', '行气活血，祛瘀止痛，增加冠脉血流量，缓解心绞痛。用于气滞血瘀型冠心病、心绞痛', '含服。一次4-6丸，一日3次；急性发作时一次10-15丸', '含服后个别出现口腔凉麻感、胃部不适；尚不明确', '对本品成份过敏者禁用；孕妇禁用', '含服后症状不缓解或加重应立即就医；疼痛持续超过15分钟不缓解，可能为心肌梗死，须立即拨打120；过敏体质者慎用', '孕妇禁用；哺乳期妇女慎用；年老体弱者在医师指导下服用', '川芎行气活血、扩张冠状动脉、抗血小板聚集，冰片开窍醒神、促进药物吸收起效', '与硝酸酯类同用注意血管扩张叠加（头痛、低血压）；与其他活血中成药叠加出血风险', '记录心绞痛发作频率、持续时间与缓解情况；发作模式改变（变频、变重）立即就医', '不能替代心肌梗死的急救；含冰片，脾胃虚寒者宜餐后含服')
ON DUPLICATE KEY UPDATE name = VALUES(name);

INSERT INTO medications (name, aliases, category, ingredients, appearance, specification, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, special_populations, pharmacology, therapeutic_duplication, monitor, notes)
VALUES ('复方丹参滴丸', '["复方丹参"]', '心血管', '丹参、三七、冰片', '棕色的滴丸；气香，味微苦', '每丸重25毫克', '滴丸剂', '活血化瘀，理气止痛。用于胸中憋闷、心绞痛（气滞血瘀证）', '口服或舌下含服。一次10丸，一日3次，4周为一疗程', '偶见胃肠道不适（恶心、胃部胀满）；个别皮疹', '孕妇禁用；对本品成份过敏者禁用', '忌生冷、辛辣、油腻食物；心绞痛持续不缓解应立即就医；与抗凝、抗血小板药同用注意出血倾向', '孕妇禁用；脾胃虚寒者饭后服用；过敏体质者慎用', '丹参活血化瘀、改善微循环，三七化瘀定痛，冰片通窍行滞；具有抗心肌缺血、抗血小板聚集作用', '与速效救心丸等其他活血化瘀中成药叠加出血风险', '与华法林、阿司匹林合用注意牙龈出血、皮肤瘀斑、黑便', '与华法林同用可增强抗凝作用，需密切监测INR；择期手术前应咨询医生是否停药')
ON DUPLICATE KEY UPDATE name = VALUES(name);

